def bubble_sort(arr):
    n = len(arr)
    for i in range(n - 1):
        for j in range(n - 1 - i):
            if arr[j] > arr[j + 1]:
                arr[j], arr[j + 1] = arr[j + 1], arr[j]
    return arr

# 示例
nums = [64, 34, 25, 12, 22, 11, 90]
print(bubble_sort(nums))  # 输出: [11, 12, 22, 25, 34, 64, 90]
